/**
 * Signs Android release builds with the venue's Play **upload key** instead
 * of the template's debug keystore (Google Play rejects debug-signed AABs).
 *
 * `android/` is generated by `expo prebuild` and git-ignored, so the signing
 * config lives here and is re-applied on every prebuild. No secret is in the
 * repo: the keystore path and passwords come from Gradle properties —
 * normally `~/.gradle/gradle.properties` on the build machine:
 *
 *   MAAJI_UPLOAD_STORE_FILE=/Users/<you>/keys/maaji-upload.jks
 *   MAAJI_UPLOAD_KEY_ALIAS=maaji-upload
 *   MAAJI_UPLOAD_STORE_PASSWORD=…
 *   MAAJI_UPLOAD_KEY_PASSWORD=…
 *
 * The property prefix is a plugin option (`propPrefix`, default "MAAJI_UPLOAD").
 * Without those properties the release build falls back to the debug key, so
 * a machine without the keystore can still build and run a release locally.
 */
const { withAppBuildGradle } = require("expo/config-plugins");

const MARKER = "// @generated withReleaseSigning";

function withReleaseSigning(config, { propPrefix = "MAAJI_UPLOAD" } = {}) {
  return withAppBuildGradle(config, (cfg) => {
    let src = cfg.modResults.contents;
    if (src.includes(MARKER)) return cfg;

    const p = (k) => `${propPrefix}_${k}`;
    const releaseConfig = `
        ${MARKER}
        release {
            if (project.hasProperty('${p("STORE_FILE")}')) {
                storeFile file(project.property('${p("STORE_FILE")}'))
                storePassword project.property('${p("STORE_PASSWORD")}')
                keyAlias project.property('${p("KEY_ALIAS")}')
                keyPassword project.property('${p("KEY_PASSWORD")}')
            }
        }`;

    // 1. Add a `release` signing config next to the template's `debug` one.
    const signingOpen = /signingConfigs\s*\{/;
    if (!signingOpen.test(src)) {
      throw new Error("withReleaseSigning: no signingConfigs block in app/build.gradle");
    }
    src = src.replace(signingOpen, (m) => `${m}${releaseConfig}`);

    // 2. Point the `release` build type at it when the upload key is
    //    configured; the template line `signingConfig signingConfigs.debug`
    //    inside `buildTypes { release { … } }` is the one replaced.
    const releaseType = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig\s+signingConfigs\.debug/;
    if (!releaseType.test(src)) {
      throw new Error("withReleaseSigning: release buildType signingConfig not found");
    }
    src = src.replace(
      releaseType,
      `$1signingConfig project.hasProperty('${p("STORE_FILE")}') ? signingConfigs.release : signingConfigs.debug`,
    );

    cfg.modResults.contents = src;
    return cfg;
  });
}

module.exports = withReleaseSigning;
